class UserService(
    private val repository: UserRepository,
    private val clock: Clock
) {
    fun activate(id: UserId) = repository.activate(id, clock.now())
}

fun createApp(): Application {
    val database = Database.connect()
    val repository = SqlUserRepository(database)
    val service = UserService(repository, SystemClock)
    return Application(service)
}
